            subject: .histoire,
            subcategory: "Époque moderne & XIXe siècle",
            lessons: [
                LessonPage(id: "course_294_pourquoi_l_irlande_affamee_exportait_intro", title: "Introduction", content: ""),
                LessonPage(id: "course_294_pourquoi_l_irlande_affamee_exportait_p1", title: "La pomme de terre, les fermiers et le mildiou", content: ""),
                LessonPage(id: "course_294_pourquoi_l_irlande_affamee_exportait_p2", title: "Les exportations : la thèse de Christine Kinealy", content: ""),
                LessonPage(id: "course_294_pourquoi_l_irlande_affamee_exportait_p3", title: "Les importations : la réponse de James Donnelly", content: ""),
