        QuizQuestion(id: "course_294_pourquoi_l_irlande_affamee_exportait_q2", type: .percentageSlider, question: "Quelle part de la récolte irlandaise de pommes de terre le mildiou détruit-il en 1845 ?", explanation: "Dès 1845, le mildiou détruit jusqu'à 50 % de la récolte nationale de pommes de terre.", correctValue: 50, sliderMin: 0, sliderMax: 100, tolerance: 5, unit: "%"),
        QuizQuestion(id: "course_294_pourquoi_l_irlande_affamee_exportait_q3", type: .trueFalse, question: "Vrai ou faux : les exportations de nourriture pendant la famine étaient organisées par le gouvernement britannique.", options: ["Vrai", "Faux"], correctIndex: 1, explanation: "Elles étaient organisées par des négociants britanniques et irlandais ; le gouvernement ne les dirigeait pas, mais il refusait de les interrompre au nom du libéralisme économique."),
