        QuizQuestion(id: "course_295_pourquoi_avons_nous_des_fuseaux_horaires_q2", type: .numericSlider, question: "En quelle année la Great Western Railway cale-t-elle ses horaires sur l'heure de Greenwich ?", explanation: "En 1840, la compagnie britannique est la première à régler tous ses trains et toutes ses gares sur l'heure de l'observatoire royal de Greenwich.", correctValue: 1840, sliderMin: 1800, sliderMax: 1900, tolerance: 5, unit: ""),
        QuizQuestion(id: "course_295_pourquoi_avons_nous_des_fuseaux_horaires_q3", type: .trueFalse, question: "Vrai ou faux : l'heure de Greenwich devient l'heure légale de la Grande-Bretagne dès 1840.", options: ["Vrai", "Faux"], correctIndex: 1, explanation: "Les chemins de fer l'adoptent en 1840 et la plupart des horloges publiques suivent dans les années 1850, mais elle ne devient l'heure légale qu'en 1880."),
